    use super::*;
    pub fn push_u8(data: &mut Vec<u8>, value: u8) { data.extend_from_slice(&value.to_le_bytes()); }
    pub fn read_u8(data: &[u8]) -> u8 {
        let mut buf = [0u8; 1];
        let len = buf.len();
        buf.copy_from_slice(&data[..len]);
        u8::from_le_bytes(buf)
    }
